+// --- RFC 6901 -------------------------------------------------------------
+
+std::string escape_pointer_token(std::string_view token) {
+  std::string out;
+  for (char c : token) {
+    if (c == '~')
+      out += "~0";
+    else if (c == '/')
+      out += "~1";
+    else
+      out += c;
+  }
+  return out;
+}
+
+std::string join(std::string_view base, std::string_view token) {
+  return std::string{base} + "/" + escape_pointer_token(token);
+}
+
+std::string join(std::string_view base, size_t index) {
+  return std::string{base} + "/" + std::to_string(index);
+}
+
+// --- Error collection -----------------------------------------------------
+
+struct collector {
+  std::vector<manifest_error> errors;
+  void add(std::string code, std::string path, std::string message) {
+    errors.push_back({std::move(code), std::move(path), std::move(message)});
+  }
+};
+
+// --- yaml-cpp helpers -----------------------------------------------------
+
+// YAML gives an untagged plain scalar the non-specific tag "?" and a quoted
+// one "!"; anything else carries an explicit tag such as "!!int".
+bool is_plain_scalar(const YAML::Node& n) {
+  return n.IsScalar() && n.Tag() == "?";
+}
+
+// Result of reading a scalar as an integer. out_of_range is still an integer
+// (an invalid_value, not a wrong_type).
+struct integer_scalar {
+  enum { not_integer, out_of_range, ok } kind = not_integer;
+  long long value = 0;
+};
+
+// Accepts only plain decimal digits with an optional leading '-'. `+1`, `0x10`,
+// `1_000` and quoted scalars such as `"1200"` are not integers.
+integer_scalar as_integer(const YAML::Node& n) {
+  if (!is_plain_scalar(n)) return {};
+  const std::string& s = n.Scalar();
+  long long v = 0;
+  const char* end = s.data() + s.size();
+  auto [p, ec] = std::from_chars(s.data(), end, v);
+  if (p != end) return {};
+  if (ec == std::errc::result_out_of_range)
+    return {.kind = integer_scalar::out_of_range};
+  if (ec != std::errc{}) return {};
+  return {.kind = integer_scalar::ok, .value = v};
+}
+
+// Depth of the deepest map the schema reads: root (0) -> models (1) ->
+// entry (2) -> experts (3).
+constexpr int max_schema_depth = 3;
+
+// YAML 1.2 requires map keys to be unique, but yaml-cpp keeps every pair and
+// its lookups return the first, so a repeated key would silently shadow its
+// twin. Returns the JSON Pointer of the first repeated scalar key. The walk
+// stops at max_schema_depth: aliases can make the node graph cyclic, and any
+// deeper collection is rejected by the schema layer anyway.
+std::optional<std::string> find_duplicate_key(
+    const YAML::Node& n, const std::string& path, int depth) {
+  if (n.IsMap()) {
+    std::unordered_set<std::string> seen;
+    for (const auto& kv : n) {
+      if (kv.first.IsScalar() && !seen.insert(kv.first.Scalar()).second)
+        return join(path, kv.first.Scalar());
+      if (depth == max_schema_depth) continue;
+      if (auto d = find_duplicate_key(kv.second,
+              join(path, kv.first.IsScalar() ? kv.first.Scalar() : std::string{}),
+              depth + 1))
+        return d;
+    }
+  } else if (n.IsSequence() && depth < max_schema_depth) {
+    for (size_t i = 0; i < n.size(); ++i)
+      if (auto d = find_duplicate_key(n[i], join(path, i), depth + 1)) return d;
+  }
+  return std::nullopt;
+}
+
+std::optional<std::string> as_string(const YAML::Node& n) {
+  if (!n.IsScalar() || n.IsNull()) return std::nullopt;
+  return n.Scalar();
+}
