+bool is_identifier(std::string_view s) {
+  // Identifiers must be usable as FUSE path components, so a leading '.' (a
+  // dotfile) is excluded.
+  if (s.empty() || s.front() == '.') return false;
+  for (unsigned char c : s) {
+    bool ok = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
+              (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-';
+    if (!ok) return false;
+  }
+  return true;
