+
+// Reports every key of `map` that is not in `valid`.
+void check_keys(const YAML::Node& map,
+    std::string_view path,
+    std::initializer_list<std::string_view> valid,
+    collector& out) {
+  std::string valid_list;
+  for (auto v : valid)
+    valid_list += (valid_list.empty() ? "" : ", ") + std::string{v};
+  for (const auto& kv : map) {
+    // A sequence, map or null key has no pointer token; report it at the map.
+    if (!kv.first.IsScalar()) {
+      out.add("unknown_key", std::string{path},
+          "map keys must be strings (valid: " + valid_list + ")");
+      continue;
+    }
+    std::string key = kv.first.Scalar();
+    bool known = false;
+    for (auto v : valid)
+      known = known || key == v;
+    if (!known)
+      out.add("unknown_key", join(path, key),
+          "unknown key '" + key + "' (valid: " + valid_list + ")");
+  }
