+std::optional<std::string> read_identifier(
+    const YAML::Node& n, const std::string& path, collector& out) {
+  auto s = as_string(n);
+  if (!s) {
+    out.add("wrong_type", path, "expected a string");
+    return std::nullopt;
+  }
+  if (!is_identifier(*s)) {
+    out.add("invalid_value", path, "must match [A-Za-z0-9._-]+ and not begin with '.'");
+    return std::nullopt;
+  }
+  return s;
