+std::optional<size_t> read_nonnegative_integer(
+    const YAML::Node& n, const std::string& path, collector& out) {
+  auto i = as_integer(n);
+  if (i.kind == integer_scalar::not_integer) {
+    out.add("wrong_type", path, "expected an integer");
+    return std::nullopt;
+  }
+  if (i.kind == integer_scalar::out_of_range) {
+    out.add("invalid_value", path, "out of range");
+    return std::nullopt;
+  }
+  if (i.value < 0) {
+    out.add("invalid_value", path, "must be >= 0");
+    return std::nullopt;
+  }
+  return static_cast<size_t>(i.value);
