+// Maps a string to the value paired with it in `choices`.
+template <typename T>
+std::optional<T> read_enum(const YAML::Node& n,
+    const std::string& path,
+    collector& out,
+    std::initializer_list<std::pair<std::string_view, T>> choices) {
+  auto s = as_string(n);
+  if (!s) {
+    out.add("wrong_type", path, "expected a string");
+    return std::nullopt;
+  }
+  std::string expected;
+  for (const auto& [spelling, value] : choices) {
+    if (*s == spelling) return value;
+    expected += (expected.empty() ? "" : " | ") + std::string{spelling};
+  }
+  out.add("invalid_value", path, "expected " + expected);
+  return std::nullopt;
