+
+std::optional<std::filesystem::path> read_abs_path(
+    const YAML::Node& n, const std::string& path, collector& out) {
+  auto s = as_string(n);
+  if (!s) {
+    out.add("wrong_type", path, "expected a string");
+    return std::nullopt;
+  }
+  if (s->find('\0') != std::string::npos) {
+    out.add("invalid_value", path, "path must not contain a NUL byte");
+    return std::nullopt;
+  }
+  std::filesystem::path p{*s};
+  if (!p.is_absolute()) {
+    out.add("invalid_value", path, "path must be absolute: '" + *s + "'");
+    return std::nullopt;
+  }
+  return p;
