+  if (const YAML::Node v = n["aliases"]) {
+    if (!v.IsSequence()) {
+      out.add("wrong_type", join(path, "aliases"), "expected a list of strings");
+    } else {
+      for (size_t i = 0; i < v.size(); ++i) {
+        const std::string at = join(join(path, "aliases"), i);
+        if (auto s = read_identifier(v[i], at, out)) {
+          e.aliases.push_back(*s);
+          pe.claims.emplace_back(*s, at);
+        }
+      }
+    }
+  }
+
+  if (const YAML::Node v = n["weight_dir"])
+    e.weight_dir = read_abs_path(v, join(path, "weight_dir"), out);
+  if (const YAML::Node v = n["experts"])
+    e.experts = parse_experts(v, join(path, "experts"), out);
+
+  if (out.errors.size() != before) pe.ok = false;
+  return pe;
+}
+
+// --- Cross-entry layer ----------------------------------------------------
+
+// Names and aliases share one file-wide namespace. Every repetition is
+// duplicate_name at the later occurrence, visiting entries in document order
+// and, within an entry, name before aliases; the message names the earlier one.
+// Entries that failed the schema layer still take part with whichever names
+// and aliases were individually valid, so a collision is reported in one pass.
+void check_uniqueness(std::vector<parsed_entry>& entries, collector& out) {
+  std::unordered_map<std::string, std::string> first_seen;  // routable name -> path
+  for (auto& pe : entries) {
+    for (const auto& [routable, at] : pe.claims) {
+      auto [it, inserted] = first_seen.emplace(routable, at);
+      if (inserted) continue;
+      out.add(
+          "duplicate_name", at, "'" + routable + "' is already used at " + it->second);
+      pe.ok = false;
+    }
+  }
+}
+
+// --- Registry layer -------------------------------------------------------
+
+// Length of the longest run of characters shared by `a` and `b`.
+size_t longest_common_substring(std::string_view a, std::string_view b) {
+  std::vector<size_t> prev(b.size() + 1), cur(b.size() + 1);
+  size_t best = 0;
+  for (char c : a) {
+    for (size_t j = 1; j <= b.size(); ++j) {
+      cur[j] = b[j - 1] == c ? prev[j - 1] + 1 : 0;
+      best = std::max(best, cur[j]);
+    }
+    std::swap(prev, cur);
+  }
+  return best;
+}
+
+std::string nearest_shapes(std::string_view shape) {
+  // Up to three slugs sharing the longest run of characters with `shape`,
+  // shortest first. Matching a substring rather than a prefix still finds
+  // `ingested-gpt-oss-20b` for `gpt-oss-20b`; below four shared characters
+  // nothing is similar enough to suggest.
+  constexpr size_t min_shared = 4;
+  std::vector<std::string_view> best;
+  size_t best_len = 0;
+  for (const auto& entry : registry_shapes()) {
+    const std::string& slug = entry.first;
+    const size_t k = longest_common_substring(shape, slug);
+    if (k > best_len) {
+      best_len = k;
+      best = {slug};
+    } else if (k == best_len) {
+      best.push_back(slug);
+    }
+  }
+  std::string s;
+  if (best_len < min_shared) return s;
+  std::stable_sort(best.begin(), best.end(),
+      [](std::string_view a, std::string_view b) { return a.size() < b.size(); });
+  best.resize(std::min<size_t>(best.size(), 3));
+  for (auto b : best)
+    s += (s.empty() ? "" : ", ") + std::string{b};
+  return s;
+}
+
+void check_registry(std::vector<parsed_entry>& entries, collector& out) {
+  const auto& shapes = registry_shapes();
+  for (size_t i = 0; i < entries.size(); ++i) {
+    if (!entries[i].ok) continue;
+    const auto& e = entries[i].entry;
+    const std::string base = join("/models", i);
+    auto it = shapes.find(e.shape);
+    if (it == shapes.end()) {
+      const std::string nearest = nearest_shapes(e.shape);
+      out.add("unknown_shape", join(base, "shape"),
+          "unknown shape '" + e.shape + "'" +
+              (nearest.empty() ? "" : " (nearest: " + nearest + ")"));
+      entries[i].ok = false;
+      continue;
+    }
+    if (e.experts && !it->second.moe) {
+      out.add("inapplicable_block", join(base, "experts"),
+          "shape '" + e.shape + "' is not a mixture-of-experts model");
+      entries[i].ok = false;
+    }
+  }
+}
+
+// --- Filesystem layer -----------------------------------------------------
+
+void check_path(const std::optional<std::filesystem::path>& p,
+    bool want_dir,
+    const std::string& path,
+    collector& out,
+    bool& ok) {
+  if (!p) return;
+  std::error_code ec;
+  bool good = want_dir ? std::filesystem::is_directory(*p, ec)
+                       : std::filesystem::is_regular_file(*p, ec);
+  if (!good) {
+    out.add("path_not_found", path,
+        p->string() + (want_dir ? " is not an existing directory"
+                                : " is not an existing regular file"));
+    ok = false;
+  }
+}
+
+void check_filesystem(std::vector<parsed_entry>& entries, collector& out) {
+  for (size_t i = 0; i < entries.size(); ++i) {
+    if (!entries[i].ok) continue;
+    const auto& e = entries[i].entry;
+    const std::string base = join("/models", i);
+    check_path(e.weight_dir, true, join(base, "weight_dir"), out, entries[i].ok);
+    if (e.experts)
+      check_path(e.experts->load_profile, false,
+          join(join(base, "experts"), "load_profile"), out, entries[i].ok);
+  }
+}
+
+}  // namespace
+
+std::expected<manifest_t, std::vector<manifest_error>> parse_manifest(
+    std::string_view yaml_text, const parse_options& opts) {
+  collector out;
+
+  // Syntax layer. A failure here stops validation: there is no document.
+  // yaml-cpp treats a raw NUL in a plain scalar as an escape character, so
+  // `/w<NUL>/a` would silently load as `/w/a`; reject NUL before parsing.
+  if (yaml_text.find('\0') != std::string_view::npos)
+    return std::unexpected(std::vector<manifest_error>{
+        {"yaml_parse_error", "", "the manifest contains a NUL byte"}});
+  YAML::Node loaded;
+  try {
+    std::vector<YAML::Node> docs = YAML::LoadAll(std::string{yaml_text});
+    if (docs.size() > 1)
+      return std::unexpected(std::vector<manifest_error>{{"yaml_parse_error", "",
+          "multi-document streams are not part of the manifest format"}});
+    if (!docs.empty()) loaded = docs.front();
+  } catch (const YAML::Exception& e) {
+    return std::unexpected(std::vector<manifest_error>{{"yaml_parse_error", "",
+        "line " + std::to_string(e.mark.line + 1) + ", column " +
+            std::to_string(e.mark.column + 1) + ": " + e.msg}});
+  }
+  // Const view: non-const operator[] on a YAML::Node can insert keys.
+  const YAML::Node& root = loaded;
+  if (auto dup = find_duplicate_key(root, "", 0))
+    return std::unexpected(std::vector<manifest_error>{
+        {"yaml_parse_error", "", "duplicate map key at '" + *dup + "'"}});
+
+  // Schema layer.
+  manifest_t result{};
+  if (!root.IsMap()) {
+    out.add("wrong_type", "", "document must be a map");
+    return std::unexpected(std::move(out.errors));
+  }
+  check_keys(root, "", {"schema_version", "models"}, out);
+
+  const YAML::Node version = root["schema_version"];
+  if (auto i = version ? as_integer(version) : integer_scalar{};
+      i.kind == integer_scalar::ok && i.value == supported_schema_version) {
+    result.schema_version = supported_schema_version;
+  } else {
+    out.add("unsupported_schema_version", "/schema_version",
+        "schema_version must be the integer " +
+            std::to_string(supported_schema_version));
+  }
+
+  std::vector<parsed_entry> entries;
+  if (const YAML::Node models = root["models"]) {
+    if (!models.IsSequence()) {
+      out.add("wrong_type", "/models", "expected a list of entries");
+    } else if (models.size() == 0) {
+      out.add("invalid_value", "/models", "at least one entry is required");
+    } else {
+      for (size_t i = 0; i < models.size(); ++i)
+        entries.push_back(parse_entry(models[i], join("/models", i), out));
+    }
+  } else {
+    out.add("missing_required_key", "/models", "'models' is required");
+  }
+
+  // Registry and filesystem layers skip entries that already failed; the
+  // cross-entry layer still counts a failed entry's individually valid names.
+  check_uniqueness(entries, out);
+  if (opts.check_registry) check_registry(entries, out);
+  if (opts.check_filesystem) check_filesystem(entries, out);
+
+  if (!out.errors.empty()) return std::unexpected(std::move(out.errors));
+  for (auto& pe : entries)
+    result.models.push_back(std::move(pe.entry));
+  return result;
+}
+
+std::expected<manifest_t, std::vector<manifest_error>> load_manifest(
+    const std::filesystem::path& file, const parse_options& opts) {
+  // Check the file kind before opening: ifstream opens a directory and reads
+  // nothing, and opening a FIFO with no writer blocks.
+  std::error_code ec;
+  if (!std::filesystem::is_regular_file(file, ec)) {
+    return std::unexpected(std::vector<manifest_error>{
+        {"path_not_found", "", "cannot read manifest file " + file.string()}});
+  }
+  std::ifstream in{file, std::ios::binary};
+  if (!in) {
+    return std::unexpected(std::vector<manifest_error>{
+        {"path_not_found", "", "cannot read manifest file " + file.string()}});
+  }
+  std::string text{std::istreambuf_iterator<char>{in}, {}};
+  return parse_manifest(text, opts);
+}
+
+std::vector<std::string> manifest_entry::routable_names() const {
+  std::vector<std::string> out;
+  out.reserve(1 + aliases.size());
+  out.push_back(name);
+  out.insert(out.end(), aliases.begin(), aliases.end());
+  return out;
+}
