+// Unit tests for the deploy-time model manifest parser. Cases pin error code
+// and path only; messages and nearest-match suggestions are free to change.
+
+#include <algorithm>
+#include <expected>
+#include <filesystem>
+#include <fstream>
+#include <map>
+#include <optional>
+#include <string>
+#include <string_view>
+#include <system_error>
+#include <unistd.h>
+#include <vector>
+
+#include <catch2/catch_test_macros.hpp>
+
+#include "tron/models/manifest.hpp"
+#include "tron/models/registry.hpp"
+
+namespace fs = std::filesystem;
+using namespace tron::models;
+
+namespace {
+
+// Registry/filesystem layers off: schema-only cases do not depend on the
+// compiled model set or on disk.
+constexpr parse_options schema_only{.check_registry = false, .check_filesystem = false};
+
+std::vector<manifest_error> errors_of(
+    std::string_view yaml, const parse_options& opts = schema_only) {
+  auto r = parse_manifest(yaml, opts);
+  REQUIRE_FALSE(r.has_value());
+  return r.error();
+}
+
+bool has_error(const std::vector<manifest_error>& errs,
+    std::string_view code,
+    std::string_view path) {
+  return std::any_of(errs.begin(), errs.end(),
+      [&](const manifest_error& e) { return e.code == code && e.path == path; });
+}
+
+// Any compiled slug. The registry is never empty in a test build.
+std::string some_shape() {
+  const auto& shapes = tron::huggingface_models_and_dirs();
+  REQUIRE_FALSE(shapes.empty());
+  return shapes.begin()->first;
+}
+
+// One `models:` list item for `shape`, named `name`, with `body` appended.
+std::string item(
+    std::string_view shape, std::string_view name, std::string_view body = "") {
+  return "  - shape: " + std::string{shape} + "\n    name: " + std::string{name} +
+         "\n" + std::string{body};
+}
+
+// A one-entry manifest for `shape`, named `name`, with `body` appended.
+std::string named_entry(
+    std::string_view shape, std::string_view name, std::string_view body = "") {
+  return "schema_version: 1\nmodels:\n" + item(shape, name, body);
+}
+
+// A one-entry manifest whose name reuses shape.
+std::string entry(std::string_view shape, std::string_view body = "") {
+  return named_entry(shape, shape, body);
+}
+
+// Scratch directory for filesystem-layer cases; removed by the destructor so
+// Catch2 cases that share this process do not see each other's files.
+struct temp_dir {
+  fs::path path;
+  explicit temp_dir(std::string const& name)
+  : path(fs::temp_directory_path() /
+         ("tron-model-manifest-test-" + std::to_string(::getpid()) + "-" + name)) {
+    fs::remove_all(path);
+    fs::create_directories(path);
+  }
+  temp_dir(const temp_dir&) = delete;
+  temp_dir& operator=(const temp_dir&) = delete;
+  ~temp_dir() {
+    std::error_code ec;
+    fs::remove_all(path, ec);
+  }
+};
+
+}  // namespace
+
+TEST_CASE("manifest: yaml syntax error", "[manifest][schema]") {
+  auto errs = errors_of("schema_version: 1\nmodels: [\n");
+  REQUIRE(errs.size() == 1);
+  CHECK(has_error(errs, "yaml_parse_error", ""));
+}
+
+TEST_CASE("manifest: duplicate map keys are rejected", "[manifest][schema]") {
+  // yaml-cpp keeps both pairs and its lookups return the first, so without
+  // this check the second weight_dir would be silently ignored.
+  auto errs = errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                        "    weight_dir: /a\n    weight_dir: /b\n");
+  REQUIRE(errs.size() == 1);
+  CHECK(has_error(errs, "yaml_parse_error", ""));
+}
+
+TEST_CASE("manifest: a raw NUL byte is rejected", "[manifest][schema]") {
+  // yaml-cpp would otherwise decode `/w<NUL>/a` as the different path `/w/a`.
+  auto errs = errors_of(
+      std::string{
+          "schema_version: 1\nmodels:\n  - shape: x\n    name: x\n    weight_dir: /w"} +
+      '\0' + "/a\n");
+  REQUIRE(errs.size() == 1);
+  CHECK(has_error(errs, "yaml_parse_error", ""));
+}
+
+TEST_CASE("manifest: multi-document streams are rejected", "[manifest][schema]") {
+  // The manifest is one document; accepting a stream would mean silently
+  // ignoring every document after the first.
+  auto errs = errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n---\n"
+                        "schema_version: 1\n");
+  REQUIRE(errs.size() == 1);
+  CHECK(has_error(errs, "yaml_parse_error", ""));
+}
+
+TEST_CASE("manifest: a cyclic alias is reported, not followed", "[manifest][schema]") {
+  // yaml-cpp links an alias to its anchored node, so this sequence contains
+  // itself. Validation must return errors rather than recurse without bound.
+  auto errs = errors_of("schema_version: 1\nmodels: &m [*m]\n");
+  CHECK(has_error(errs, "wrong_type", "/models/0"));
+}
+
+TEST_CASE(
+    "manifest: schema_version must equal the supported version", "[manifest][schema]") {
+  SECTION("missing") {
+    CHECK(has_error(errors_of("models:\n  - shape: x\n    name: x\n"),
+        "unsupported_schema_version", "/schema_version"));
+  }
+  SECTION("non-integer") {
+    CHECK(has_error(
+        errors_of("schema_version: '1'\nmodels:\n  - shape: x\n    name: x\n"),
+        "unsupported_schema_version", "/schema_version"));
+  }
+  SECTION("wrong value") {
+    CHECK(
+        has_error(errors_of("schema_version: 2\nmodels:\n  - shape: x\n    name: x\n"),
+            "unsupported_schema_version", "/schema_version"));
+  }
+}
+
+TEST_CASE("manifest: unknown keys are errors at every level", "[manifest][schema]") {
+  auto errs = errors_of("schema_version: 1\n"
+                        "extra: 1\n"
+                        "models:\n"
+                        "  - shape: x\n"
+                        "    name: x\n"
+                        "    bogus: 1\n"
+                        "    experts:\n"
+                        "      replica: 3\n");
+  CHECK(has_error(errs, "unknown_key", "/extra"));
+  CHECK(has_error(errs, "unknown_key", "/models/0/bogus"));
+  CHECK(has_error(errs, "unknown_key", "/models/0/experts/replica"));
+}
+
+TEST_CASE("manifest: missing required keys", "[manifest][schema]") {
+  CHECK(has_error(errors_of("schema_version: 1\n"), "missing_required_key", "/models"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - name: foo\n"),
+      "missing_required_key", "/models/0/shape"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n"),
+      "missing_required_key", "/models/0/name"));
+}
+
+TEST_CASE("manifest: wrong types", "[manifest][schema]") {
+  CHECK(
+      has_error(errors_of("schema_version: 1\nmodels: {}\n"), "wrong_type", "/models"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    aliases: foo\n"),
+      "wrong_type", "/models/0/aliases"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    experts:\n      replicas: '1200'\n"),
+      "wrong_type", "/models/0/experts/replicas"));
+}
+
+TEST_CASE("manifest: invalid values", "[manifest][schema]") {
+  CHECK(has_error(
+      errors_of("schema_version: 1\nmodels: []\n"), "invalid_value", "/models"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    aliases: ['has space']\n"),
+      "invalid_value", "/models/0/aliases/0"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n"
+                            "    name: 'has space'\n"),
+      "invalid_value", "/models/0/name"));
+  // A leading '.' would make the identifier unusable as a FUSE path component.
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n"
+                            "    name: .hidden\n"),
+      "invalid_value", "/models/0/name"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    weight_dir: relative/dir\n"),
+      "invalid_value", "/models/0/weight_dir"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    experts:\n      replicas: -1\n"),
+      "invalid_value", "/models/0/experts/replicas"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    experts:\n      replicas: 99999999999999999999\n"),
+      "invalid_value", "/models/0/experts/replicas"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    experts:\n      placement: sideways\n"),
+      "invalid_value", "/models/0/experts/placement"));
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    experts:\n      routing: random\n"),
+      "invalid_value", "/models/0/experts/routing"));
+  // Replicas with placement none are rejected, as with the legacy CLI flags.
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    experts:\n      replicas: 4\n      placement: none\n"),
+      "invalid_value", "/models/0/experts/replicas"));
+  // A double-quoted YAML escape decodes to a NUL byte; stat() would validate
+  // only the prefix before it while the full string is stored.
+  CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: x\n    name: x\n"
+                            "    weight_dir: \"/mnt/w\\0junk\"\n"),
+      "invalid_value", "/models/0/weight_dir"));
+}
