+TEST_CASE("manifest: routable names share one namespace", "[manifest][cross]") {
+  auto s = some_shape();
+  auto two = [&](std::string_view first, std::string_view second) {
+    return errors_of(
+        "schema_version: 1\nmodels:\n" + std::string{first} + std::string{second});
+  };
+  SECTION("two entries share a name") {
+    auto errs = two(item(s, "x"), item(s, "x"));
+    CHECK(has_error(errs, "duplicate_name", "/models/1/name"));
+  }
+  SECTION("an alias repeats another entry's name") {
+    auto errs = two(item(s, "x"), item(s, "y", "    aliases: [x]\n"));
+    CHECK(has_error(errs, "duplicate_name", "/models/1/aliases/0"));
+  }
+  SECTION("a name repeats an earlier entry's alias") {
+    auto errs = two(item(s, "a", "    aliases: [x]\n"), item(s, "x"));
+    CHECK(has_error(errs, "duplicate_name", "/models/1/name"));
+  }
+  SECTION("two entries share an alias") {
+    auto errs =
+        two(item(s, "a", "    aliases: [x]\n"), item(s, "b", "    aliases: [y, x]\n"));
+    CHECK(has_error(errs, "duplicate_name", "/models/1/aliases/1"));
+  }
+  SECTION("an alias repeats its own entry's name, whichever key is written first") {
+    CHECK(has_error(errors_of(named_entry(s, "x", "    aliases: [x]\n")),
+        "duplicate_name", "/models/0/aliases/0"));
+    CHECK(has_error(errors_of("schema_version: 1\nmodels:\n  - shape: " + s +
+                              "\n    aliases: [x]\n    name: x\n"),
+        "duplicate_name", "/models/0/aliases/0"));
+  }
+  SECTION("an alias is repeated within one entry") {
+    auto errs = errors_of(named_entry(s, "a", "    aliases: [x, x]\n"));
+    CHECK(has_error(errs, "duplicate_name", "/models/0/aliases/1"));
+  }
+  SECTION("shape is not part of the namespace") {
+    // name == shape beside name == shape-foo, and an alias equal to another
