+
+TEST_CASE("manifest: a schema failure suppresses the registry and filesystem layers "
+          "for that entry",
+    "[manifest]") {
+  // Entry 0 fails the schema layer with an unknown key, and would also fail
+  // the registry layer (bogus shape) and the filesystem layer (missing
+  // absolute directory). Only the schema error must be reported.
+  auto errs = errors_of(
+      entry("no-such-shape-xyz", "    bogus: 1\n    weight_dir: /definitely/missing\n"),
+      parse_options{.check_registry = true, .check_filesystem = true});
+  CHECK(errs.size() == 1);
+  CHECK(has_error(errs, "unknown_key", "/models/0/bogus"));
+  CHECK_FALSE(has_error(errs, "unknown_shape", "/models/0/shape"));
+  CHECK_FALSE(has_error(errs, "path_not_found", "/models/0/weight_dir"));
+
+  // The cross-entry layer is the exception: a rejected entry's individually
+  // valid aliases still claim their names, so a collision with a later entry
+  // is reported in the same pass instead of after the first error is fixed.
+  auto unnamed = errors_of(
+      "schema_version: 1\nmodels:\n  - shape: x\n    aliases: [y]\n" + item("x", "y"));
+  CHECK(unnamed.size() == 2);
+  CHECK(has_error(unnamed, "missing_required_key", "/models/0/name"));
+  CHECK(has_error(unnamed, "duplicate_name", "/models/1/name"));
+}
+
+// An entry's routable names are its name followed by its aliases, and
+// `aliases: []` is equivalent to omitting aliases.
+TEST_CASE("manifest: identity", "[manifest]") {
+  auto s = some_shape();
+  SECTION("name reusing the shape parses with empty aliases") {
+    auto r = parse_manifest(entry(s), schema_only);
+    REQUIRE(r.has_value());
+    REQUIRE(r->models.size() == 1);
+    CHECK(r->models[0].name == s);
+    CHECK(r->models[0].aliases.empty());
+    CHECK_FALSE(r->models[0].weight_dir.has_value());
+    CHECK_FALSE(r->models[0].experts.has_value());
+  }
+  SECTION("an explicit empty aliases list is equivalent to omission") {
+    auto r = parse_manifest(entry(s, "    aliases: []\n"), schema_only);
+    REQUIRE(r.has_value());
+    CHECK(r->models[0].aliases.empty());
+  }
+  SECTION("routable names are name, then aliases") {
+    // Rinzler takes the first routable name as the canonical key, and keys
+    // the entry's expert settings on `name`, so `name` must come first.
+    auto r = parse_manifest(named_entry(s, "a", "    aliases: [c, b]\n"), schema_only);
+    REQUIRE(r.has_value());
+    CHECK(r->models[0].routable_names() == std::vector<std::string>{"a", "c", "b"});
+  }
+}
