+TEST_CASE("collect_tool_calls: parallel ministral - multiple calls as json array",
+    "[tool_call_serialize]") {
+  // Ministral supports parallel tool calls via json_array format with multiple
+  // tool calls in a single turn. Verify both calls are collected, order is
+  // preserved, and all call details are intact.
+  std::vector<std::string> texts = {R"([
+    {"name":"get_weather","arguments":{"city":"SF"}},
+    {"name":"get_time","arguments":{"tz":"UTC"}}
+  ])"};
+  std::vector<std::optional<std::string>> names;
+  auto result = rinzler::collect_tool_calls(
+      texts, names, rinzler::tool_call_payload_format::json_array);
+  REQUIRE(result.parsed.size() == 2);
+  CHECK(result.parsed[0].name == "get_weather");
+  CHECK(result.parsed[0].arguments_json == R"({"city":"SF"})");
+  CHECK(result.parsed[1].name == "get_time");
+  CHECK(result.parsed[1].arguments_json == R"({"tz":"UTC"})");
+  CHECK_FALSE(result.had_partial_failure);
+}
+
+TEST_CASE("collect_tool_calls: parallel ministral - same-name calls both collected",
+    "[tool_call_serialize]") {
+  // Parallel tool calls with the same function name but different arguments
+  // should both be collected (not deduplicated). Deduplication only suppresses
+  // identical calls (same name and same arguments), not different calls.
+  std::vector<std::string> texts = {R"([
+    {"name":"get_weather","arguments":{"city":"SF"}},
+    {"name":"get_weather","arguments":{"city":"NYC"}}
+  ])"};
+  std::vector<std::optional<std::string>> names;
+  auto result = rinzler::collect_tool_calls(
+      texts, names, rinzler::tool_call_payload_format::json_array);
+  REQUIRE(result.parsed.size() == 2);
+  CHECK(result.parsed[0].name == "get_weather");
+  CHECK(result.parsed[0].arguments_json == R"({"city":"SF"})");
+  CHECK(result.parsed[1].name == "get_weather");
+  CHECK(result.parsed[1].arguments_json == R"({"city":"NYC"})");
+  CHECK(result.suppressed_duplicate_count == 0);
+  CHECK_FALSE(result.had_partial_failure);
+}
+
+TEST_CASE(
+    "collect_tool_calls: parallel ministral - malformed element fails entire array",
+    "[tool_call_serialize]") {
+  // When parsing parallel tool calls in json_array format, all-or-nothing
+  // semantics apply: a malformed element in any call causes the entire
+  // array to fail parsing and fall back to content.
+  std::vector<std::string> texts = {R"([
+    {"name":"get_weather","arguments":{"city":"SF"}},
+    {"not_a_valid":"element"}
+  ])"};
+  std::vector<std::optional<std::string>> names;
+  auto result = rinzler::collect_tool_calls(
+      texts, names, rinzler::tool_call_payload_format::json_array);
+  // Malformed element → entire array fails
+  CHECK(result.parsed.empty());
+  CHECK(result.had_partial_failure);
+  CHECK_FALSE(result.fallback_text.empty());
+}
